import Fastify from 'fastify'
import dotenv from 'dotenv'
import { supabase } from './config/database'

dotenv.config()

const PORT = Number(process.env.PORT) || 3000
const APP_NAME = process.env.APP_NAME || 'Planner'

const server = Fastify({ logger: true })

// ── Existing routes ──────────────────────────────────

server.get('/health', async (request, reply) => {
  return {
    status: 'ok',
    app: APP_NAME,
    timestamp: new Date().toISOString()
  }
})

server.get('/hello/:name', async (request, reply) => {
  const { name } = request.params as { name: string }
  return {
    message: `Hello ${name}, welcome to ${APP_NAME}!`
  }
})

// ── NEW: Database test route ─────────────────────────

server.get('/db-test', async (request, reply) => {

  // Query the users table we just created
  const { data, error } = await supabase
    .from('users')
    .select('*')

  // If something went wrong with the query
  if (error) {
    return reply.status(500).send({
      error: 'Database query failed',
      details: error.message
    })
  }

  // Return the users we get back
  return {
    message: 'Database connected successfully',
    userCount: data.length,
    users: data
  }
})

// ── Start server ─────────────────────────────────────

const start = async () => {
  try {
    await server.listen({ port: PORT, host: '0.0.0.0' })
    console.log(`\n✅ ${APP_NAME} is running on http://localhost:${PORT}`)
    console.log(`👉 Test DB: http://localhost:${PORT}/db-test\n`)
  } catch (err) {
    server.log.error(err)
    process.exit(1)
  }
}

start()
